// using Microsoft.VisualBasic.Devices;

public class ISMBatchableTelemetryWorkingMemoryTaskService extends ISMBatchableTelemetryTaskService
{
}

Method.Source:
public void collectTelemetry(ISMBatchableTelemetryParameterSetup _parameterSetup)
{
    ISMBatchableTelemetryWorkingMemory workingMemory = ISMBatchableTelemetryWorkingMemory::construct();

    System.Diagnostics.PerformanceCounter memoryPerformanceCounter =
        new System.Diagnostics.PerformanceCounter('Memory', 'Available MBytes');
    real totalAvailableRAM = memoryPerformanceCounter.RawValue;

    /*
    Microsoft.VisualBasic.Devices.ComputerInfo computerInfo =
        new Microsoft.VisualBasic.Devices.ComputerInfo();
    real totalPhysicalMemory = computerInfo.TotalPhysicalMemory / 1024 / 1024;
    */

    workingMemory.processMetric(totalAvailableRAM);
}
